(function(){
'use strict';
const D=window.AFTERFALL,$=id=>document.getElementById(id);
const state={category:'all',search:'',zone:'all',status:'all',page:1,pageSize:10,lastHash:'#overview'};
const names=Object.fromEntries(D.categories.map(c=>[c.id,c.name]));
const glyphs={all:'▤',arena:'◇',complex:'▦',wanted:'⚑',faction:'⌂',quest:'◉',event:'✧'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const badge=e=>`<span class="category-badge ${e.category}">${names[e.category]}</span>`;
let toastTimer;
function toast(text){$('toast').textContent=text;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),2200);}
function setMobile(open){document.body.classList.toggle('nav-open',open);$('menuButton').setAttribute('aria-expanded',String(open));}
function nav(){const all=[{id:'all',name:'全部内容'},...D.categories];$('categoryNav').innerHTML=all.map(c=>`<a class="nav-item ${state.category===c.id?'active':''}" ${state.category===c.id?'aria-current="page"':''} href="${c.id==='all'?'#overview':'#category/'+c.id}"><span class="nav-icon" aria-hidden="true">${glyphs[c.id]}</span><span>${c.name}</span><span class="nav-count">${c.id==='all'?D.entries.length:D.entries.filter(e=>e.category===c.id).length}</span></a>`).join('');}
function metrics(){const defs=[['▤','收录内容',D.entries.length,'项','含任务路线与未启用预设'],['⌂','生成入口启用',D.entries.filter(e=>e.status==='enabled').length,'项','受落点与事件条件约束'],['◇','独立战场',D.entries.filter(e=>e.category==='arena').length,'项','两档铃铛洞穴分别计数'],['◷','未启用预设',D.entries.filter(e=>e.status==='inactive').length,'项','保留配置，单独标注']];$('metrics').innerHTML=defs.map(([icon,label,n,unit,desc])=>`<div class="metric"><div class="metric-label"><span class="metric-icon" aria-hidden="true">${icon}</span>${label}</div><div class="metric-value">${n}<small>${unit}</small></div><p class="metric-desc">${desc}</p></div>`).join('');}
function filtered(){const q=state.search.trim().toLocaleLowerCase();return D.entries.filter(e=>(state.category==='all'||e.category===state.category)&&(state.status==='all'||e.status===state.status)&&(state.zone==='all'||e.zones.includes(Number(state.zone)))&&(!q||JSON.stringify(e).toLocaleLowerCase().includes(q)));}
function renderTable(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/state.pageSize));state.page=Math.max(1,Math.min(state.page,pages));const start=(state.page-1)*state.pageSize;const rows=list.slice(start,start+state.pageSize);$('categoryLabel').textContent=state.category==='all'?'全部内容':names[state.category];$('catalogTitle').firstChild.textContent=state.category==='all'?'全览目录 ':'分类目录 ';$('resultCount').innerHTML=`共 <strong>${list.length}</strong> 项${state.category!=='all'?' · '+names[state.category]:''}${state.search?' · 搜索“'+esc(state.search)+'”':''}`;$('catalogBody').innerHTML=rows.map(e=>`<tr class="${e.status==='inactive'?'inactive-row':''}"><td><div class="entry-title-wrap"><span class="entry-glyph ${e.category}" aria-hidden="true">${glyphs[e.category]}</span><div><button class="entry-link" data-open="${e.id}">${esc(e.name)}</button><div class="entry-subtitle">${esc(e.alias)}</div></div></div></td><td>${badge(e)}</td><td>${esc(e.zone)}<div class="row-size">${esc(e.size)}</div></td><td>${esc(e.encounter)}</td><td>${esc(e.reward)}</td><td>${esc(e.reset)}${e.status==='inactive'?'<br><span class="inactive-label">未启用</span>':''}</td><td><button class="row-open" data-open="${e.id}" aria-label="查看${esc(e.name)}详情">＋</button></td></tr>`).join('');$('emptyState').hidden=list.length!==0;$('pageInfo').textContent=list.length?`显示 ${start+1}–${Math.min(start+state.pageSize,list.length)}，共 ${list.length} 项`:'共 0 项';$('pageNumber').textContent=state.page+' / '+pages;$('prevPage').disabled=state.page<=1;$('nextPage').disabled=state.page>=pages;}
function listItems(items){return `<ul class="detail-list">${items.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul>`;}
function showDetail(id){const e=D.entries.find(x=>x.id===id);if(!e){location.hash='overview';return;}state.category=e.category;nav();$('overviewView').hidden=true;$('methodView').hidden=true;$('detailView').hidden=false;const pos=D.entries.indexOf(e),related=e.relations.map(id=>D.entries.find(x=>x.id===id)).filter(Boolean);$('detailView').innerHTML=`<div class="detail-top"><button class="back-button" data-back><span aria-hidden="true">‹</span> 返回总览表</button><span class="detail-counter">${String(pos+1).padStart(2,'0')} / ${D.entries.length} 条目</span></div><div class="detail-heading"><div><div class="detail-kicker">${badge(e)}<span class="detail-alias">${esc(e.alias)}</span>${e.status==='inactive'?'<span class="inactive-label">未启用</span>':''}</div><h1>${esc(e.name)}</h1><p class="detail-summary">${esc(e.summary)}</p></div><div class="detail-actions"><button class="secondary-button" data-copy="${e.id}">复制详情链接</button><button class="secondary-button" data-download="${e.id}">下载本项详解</button></div></div><div class="detail-facts">${[['区域与占地',e.zone+' · '+e.size],['开启 / 生成',e.trigger],['战斗结构',e.encounter],['刷新与进度',e.reset]].map(([t,v])=>`<div class="fact"><span>${t}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="detail-layout"><div class="detail-main"><section class="detail-section"><h2><span class="heading-square"></span>完整玩法流程</h2>${e.flow.map(([t,p])=>`<div class="flow-step"><h3>${esc(t)}</h3><p>${esc(p)}</p></div>`).join('')}</section><section class="detail-section"><h2><span class="heading-square"></span>战斗配置</h2>${e.combat.map(([t,p])=>`<div class="combat-row"><strong>${esc(t)}</strong><p>${esc(p)}</p></div>`).join('')}</section><section class="detail-section"><h2><span class="heading-square"></span>奖励与回访循环</h2>${listItems(e.rewards)}<div class="repeat-label">重置与完成判定</div><p class="repeat-text">${esc(e.repeat)}</p></section><section class="design-section"><div class="section-eyebrow">DESIGN READING · 基于机制的归纳</div><h2>这条路线在生存循环中的作用</h2><p>${esc(e.design)}</p></section>${e.notes.length?`<section class="detail-note"><strong>阅读边界</strong><ul>${e.notes.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul></section>`:''}<details class="source-disclosure"><summary>静态脚本与预设依据 <span>${e.sources.length} 条来源 · 点击展开</span></summary>${e.sources.map(s=>`<div class="source-item"><code>${esc(s.path)}</code><small>${s.lines?'已核对行段：'+esc(s.lines):'脚本内容 / 预设生成点与配置'}</small></div>`).join('')}</details></div><aside class="detail-aside"><section class="aside-card"><h2>进入前的准备</h2>${e.materials.length?'<ul>'+e.materials.map(t=>'<li>'+esc(t)+'</li>').join('')+'</ul>':'<p>未记录必须提交的专用开门材料。战斗与返程补给按当前队伍配置准备。</p>'}</section>${e.hazards.length?`<section class="aside-card hazard-card"><h2>场景风险与特殊规则</h2><ul>${e.hazards.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul></section>`:''}<section class="aside-card"><h2>主要收益</h2><p>${esc(e.reward)}</p>${related.length?'<h2 style="margin-top:23px">相关路线</h2>'+related.map(r=>`<a class="relation-link" href="#entry/${r.id}">${esc(r.name)}</a>`).join(''):''}</section><section class="aside-card"><h2>静态快照</h2><p>2026.11.19<br>基础配置可受模式倍率影响。生成入口启用不代表本局必定落地。</p></section></aside></div><div class="detail-pagination">${pos>0?`<button data-open="${D.entries[pos-1].id}"><small>上一项</small>${esc(D.entries[pos-1].name)}</button>`:'<span></span>'}${pos<D.entries.length-1?`<button data-open="${D.entries[pos+1].id}"><small>下一项</small>${esc(D.entries[pos+1].name)}</button>`:''}</div>`;document.title=e.name+' · After Fall 图鉴';}
function showMethod(){nav();$('overviewView').hidden=true;$('detailView').hidden=true;$('methodView').hidden=false;const cards=[['复核范围',D.method.scope],['怎样读条目数量',D.method.counts],['怎样避免漏读',D.method.evidence],['静态分析的边界',D.method.limits]];$('methodView').innerHTML=`<div class="detail-top"><button class="back-button" data-back><span aria-hidden="true">‹</span> 返回总览表</button><span class="detail-counter">2026.11.19 静态快照</span></div><div class="method-header"><div class="eyebrow">METHOD & SCOPE</div><h1>复核说明与阅读口径</h1><p>这是一份以玩法为主线、以脚本为依据的图鉴。把生成、战斗、收益和回访放在一起阅读，比单看模型名称更接近实际玩法结构。</p></div><div class="method-grid">${cards.map(([t,p])=>`<section class="detail-section"><h2>${t}</h2><p>${esc(p)}</p></section>`).join('')}</div><section class="detail-section" style="margin-bottom:24px"><h2>这次补齐了什么</h2>${listItems(D.method.corrections)}</section><div class="method-downloads"><a class="secondary-button" href="docs/overview.csv" download>总览表 CSV</a><a class="secondary-button" href="docs/overview.md" download>总览表 Markdown</a><a class="secondary-button" href="docs/details.md" download>完整逐项详解</a><a class="secondary-button" href="docs/catalog.json" download>结构化资料 JSON</a><a class="secondary-button" href="docs/static-review.md" download>原始复核清单</a></div>`;document.title='复核说明 · After Fall 图鉴';}
function route(){setMobile(false);const hash=decodeURIComponent(location.hash||'#overview');if(hash.startsWith('#entry/')){showDetail(hash.slice(7));}else if(hash==='#method'){showMethod();}else{const cat=hash.startsWith('#category/')?hash.slice(10):'all';if(cat!=='all'&&!names[cat]){location.hash='overview';return;}if(state.lastHash!==hash)state.page=1;state.lastHash=hash;state.category=cat;nav();$('overviewView').hidden=false;$('detailView').hidden=true;$('methodView').hidden=true;renderTable();document.title=D.title;}window.scrollTo(0,0);}
function reset(){state.search='';state.zone='all';state.status='all';state.page=1;$('searchInput').value='';$('zoneFilter').value='all';$('statusFilter').value='all';renderTable();}
function markdown(e){return [`# ${e.name}`,'',`${names[e.category]} · ${e.zone} · ${e.size}`,'',e.summary,'',...e.flow.flatMap(([t,p])=>['## '+t,'',p,'']),'## 战斗配置','',...e.combat.map(([t,p])=>'- '+t+'：'+p),'','## 奖励与循环','',...e.rewards.map(r=>'- '+r),'',e.repeat,'','## 设计解读','',e.design,'','## 静态依据','',...e.sources.map(s=>'- `'+s.path+'` '+s.lines),'',D.method.limits].join('\n');}
function downloadEntry(id){const e=D.entries.find(x=>x.id===id);if(!e)return;const blob=new Blob([markdown(e)],{type:'text/markdown;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=e.name+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('本项详解已生成');}
// ---- 单页 PDF 导出：按页面表格样式渲染全部条目，页面尺寸随内容而定 ----
const PDF_CSS=[
'.pdf-sheet{width:1180px;box-sizing:border-box;background:#fff;color:#647961;font-family:Inter,"Segoe UI","Microsoft YaHei","PingFang SC",sans-serif;font-size:12px;line-height:1.65}',
'.pdf-sheet *{box-sizing:border-box}',
'.pdf-sheet .pdf-head{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;padding:34px 40px 20px;border-bottom:2px solid #e6ebe1}',
'.pdf-sheet .pdf-title{font-size:23px;font-weight:700;color:#213436;letter-spacing:.01em}',
'.pdf-sheet .pdf-sub{margin-top:8px;font-size:10px;font-weight:600;letter-spacing:.16em;color:#91a096}',
'.pdf-sheet .pdf-meta{font-size:10.5px;color:#83948b;text-align:right;line-height:1.9}',
'.pdf-sheet .pdf-table{padding:0 40px}',
'.pdf-sheet table{width:100%;table-layout:fixed;border-collapse:collapse}',
'.pdf-sheet th{text-align:left;background:#f8faf5;font-size:10.5px;color:#87967d;font-weight:500;padding:13px 12px;border-bottom:1px solid #e6ebe1;white-space:nowrap}',
'.pdf-sheet th:nth-child(1){width:25%}.pdf-sheet th:nth-child(2){width:9%}.pdf-sheet th:nth-child(3){width:13%}.pdf-sheet th:nth-child(4){width:19%}.pdf-sheet th:nth-child(5){width:18%}.pdf-sheet th:nth-child(6){width:16%}',
'.pdf-sheet td{padding:16px 12px;border-bottom:1px solid #edf0e9;font-size:11.6px;line-height:1.65;vertical-align:middle;color:#647961;overflow-wrap:anywhere}',
'.pdf-sheet tbody tr:last-child td{border-bottom:0}',
'.pdf-sheet .entry-title-wrap{display:flex;gap:10px;align-items:center}',
'.pdf-sheet .entry-glyph{width:34px;height:37px;border:1px solid #e3e8df;border-radius:5px;display:grid;place-items:center;flex-shrink:0;color:#8d9f80;background:#f7f9f2;font-size:15px}',
'.pdf-sheet .entry-glyph.arena{background:#faf0e6;border-color:#f0decd;color:#b57a4a}',
'.pdf-sheet .entry-glyph.complex{background:#edf4eb;border-color:#dce8d6;color:#6b9255}',
'.pdf-sheet .entry-glyph.wanted{background:#f5eee9;border-color:#e9ded4;color:#9f8363}',
'.pdf-sheet .entry-link{display:block;color:#2a412b;font-size:13px;font-weight:600;line-height:1.5}',
'.pdf-sheet .inactive-row .entry-link{color:#84917f}',
'.pdf-sheet .entry-subtitle{font-size:9.8px;color:#a1ac98;margin-top:3px}',
'.pdf-sheet .row-size{font-size:10.3px;color:#a2ae98;margin-top:2px}',
'.pdf-sheet .category-badge{display:inline-block;padding:3px 7px;border-radius:4px;background:#f0f3eb;border:1px solid #e3e9da;font-size:10.3px;color:#788b64;white-space:nowrap}',
'.pdf-sheet .category-badge.arena{background:#fdf0e5;border-color:#f0ddc9;color:#b27a45}',
'.pdf-sheet .category-badge.wanted{background:#f4ede5;border-color:#e8ddce;color:#9d8261}',
'.pdf-sheet .category-badge.quest{background:#edf1f8;border-color:#e0e6f0;color:#7686a1}',
'.pdf-sheet .category-badge.event{background:#f3f2e8;border-color:#e6e4d6;color:#9c976c}',
'.pdf-sheet .category-badge.faction{background:#eef3ef;border-color:#dde7df;color:#749583}',
'.pdf-sheet .inactive-label{display:inline-block;border:1px solid #dfdeda;background:#f4f3f0;color:#9a978e;padding:1px 5px;font-size:10px;border-radius:3px;margin-top:5px}',
'.pdf-sheet .pdf-foot{display:flex;justify-content:space-between;gap:24px;margin:0 40px;padding:14px 0 30px;border-top:1px solid #e8ede1;font-size:10px;color:#93a183}'
].join('');
const snapshotText=()=>String(D.snapshot).replaceAll('-','.');
function pdfRow(e){return `<tr class="${e.status==='inactive'?'inactive-row':''}"><td><div class="entry-title-wrap"><span class="entry-glyph ${e.category}" aria-hidden="true">${glyphs[e.category]}</span><div><span class="entry-link">${esc(e.name)}</span><div class="entry-subtitle">${esc(e.alias)}</div></div></div></td><td>${badge(e)}</td><td>${esc(e.zone)}<div class="row-size">${esc(e.size)}</div></td><td>${esc(e.encounter)}</td><td>${esc(e.reward)}</td><td>${esc(e.reset)}${e.status==='inactive'?'<div><span class="inactive-label">未启用</span></div>':''}</td></tr>`;}
function pdfSheet(){const el=document.createElement('div');el.className='pdf-sheet';el.innerHTML=`<style>${PDF_CSS}</style><div class="pdf-head"><div><div class="pdf-title">AFTER FALL · 副本与据点总览</div><div class="pdf-sub">ENCOUNTER INDEX · 全部 ${D.entries.length} 项</div></div><div class="pdf-meta">静态快照 ${snapshotText()}<br>Place ${esc(D.placeId)}<br>全部条目 · 不受当前筛选与分页影响</div></div><div class="pdf-table"><table><thead><tr><th>副本 / 据点</th><th>分类</th><th>区域 / 占地</th><th>战斗结构</th><th>主要收益</th><th>刷新 / 状态</th></tr></thead><tbody>${D.entries.map(pdfRow).join('')}</tbody></table></div><div class="pdf-foot"><span>After Fall 玩法档案 / Field Guide · ${snapshotText()} 静态快照</span><span>${esc(D.method.counts)}</span></div>`;return el;}
function svgImage(svg){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('浏览器未渲染表格图层'));img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);});}
function dataUrlBytes(url){const bin=atob(url.slice(url.indexOf(',')+1)),out=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)out[i]=bin.charCodeAt(i);return out;}
function pdfDocument(jpeg,pxW,pxH,cssW,cssH){let ptW=Math.round(cssW*.75),ptH=Math.round(cssH*.75);const fit=Math.min(1,14000/Math.max(ptW,ptH,1));ptW=Math.max(1,Math.round(ptW*fit));ptH=Math.max(1,Math.round(ptH*fit));const enc=new TextEncoder(),chunks=[],offsets=[];let size=0;const raw=a=>{chunks.push(a);size+=a.length;},text=s=>raw(enc.encode(s));const stream=(n,dict,data)=>{offsets[n]=size;text(n+' 0 obj\n<< '+dict+' /Length '+data.length+' >>\nstream\n');raw(data);text('\nendstream\nendobj\n');};raw(new Uint8Array([37,80,68,70,45,49,46,52,10,37,226,227,207,211,10]));offsets[1]=size;text('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n');offsets[2]=size;text('2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n');offsets[3]=size;text('3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 '+ptW+' '+ptH+'] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>\nendobj\n');stream(4,'/Type /XObject /Subtype /Image /Width '+pxW+' /Height '+pxH+' /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode',jpeg);stream(5,'',enc.encode('q\n'+ptW+' 0 0 '+ptH+' 0 0 cm\n/Im0 Do\nQ\n'));const xref=size;let table='xref\n0 6\n0000000000 65535 f \n';for(let n=1;n<=5;n++)table+=String(offsets[n]).padStart(10,'0')+' 00000 n \n';text(table+'trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n'+xref+'\n%%EOF\n');const out=new Uint8Array(size);let at=0;for(const c of chunks){out.set(c,at);at+=c.length;}return out;}
async function buildPdfFile(){const sheet=pdfSheet(),host=document.createElement('div');host.style.cssText='position:fixed;left:-20000px;top:0;width:1180px;pointer-events:none;';host.appendChild(sheet);document.body.appendChild(host);try{const rect=sheet.getBoundingClientRect(),w=Math.ceil(rect.width),h=Math.ceil(rect.height);const scale=Math.max(.4,Math.min(2.5,Math.sqrt(16000000/(w*h)),8000/Math.max(w,h)));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(w*scale));canvas.height=Math.max(1,Math.round(h*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);const svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+canvas.width+'" height="'+canvas.height+'" viewBox="0 0 '+w+' '+h+'"><foreignObject x="0" y="0" width="'+w+'" height="'+h+'">'+new XMLSerializer().serializeToString(sheet)+'</foreignObject></svg>';const img=await svgImage(svg);ctx.drawImage(img,0,0,canvas.width,canvas.height);const probe=(x,y)=>{x=Math.max(0,Math.min(canvas.width-1,Math.round(x)));y=Math.max(0,Math.min(canvas.height-1,Math.round(y)));const d=ctx.getImageData(x,y,Math.min(120,canvas.width-x),Math.min(120,canvas.height-y)).data;for(let i=0;i<d.length;i+=4)if(d[i]<250||d[i+1]<250||d[i+2]<250)return true;return false;};if(!probe(40*scale,40*scale)&&!probe(canvas.width/2-60,canvas.height/2)&&!probe(canvas.width/2-60,canvas.height-160*scale))throw new Error('表格图层未渲染');const jpeg=dataUrlBytes(canvas.toDataURL('image/jpeg',.94));return {blob:new Blob([pdfDocument(jpeg,canvas.width,canvas.height,w,h)],{type:'application/pdf'}),name:'AfterFall-副本与据点总览-'+D.snapshot+'.pdf'};}finally{host.remove();}}
async function exportPdf(){const btn=$('exportPdf');if(!btn||btn.disabled)return;const original=btn.innerHTML;btn.disabled=true;btn.innerHTML='<span aria-hidden="true">…</span> 生成中';try{const {blob,name}=await buildPdfFile();const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>a.remove(),1000);setTimeout(()=>URL.revokeObjectURL(url),5000);toast('PDF 已生成：单页 · 全部 '+D.entries.length+' 项');}catch(err){console.error(err);toast('PDF 导出失败，请用 Chrome 或 Edge 打开本页重试');}finally{btn.disabled=false;btn.innerHTML=original;}}
document.addEventListener('click',async ev=>{const open=ev.target.closest('[data-open]');if(open){location.hash='entry/'+open.dataset.open;return;}if(ev.target.closest('[data-back]')){location.hash=state.lastHash;return;}const dl=ev.target.closest('[data-download]');if(dl){downloadEntry(dl.dataset.download);return;}const copy=ev.target.closest('[data-copy]');if(copy){try{await navigator.clipboard.writeText(location.href);toast('详情链接已复制');}catch{toast('请复制浏览器地址栏中的详情链接');}}if(ev.target.closest('#sidebar a'))setMobile(false);});
$('searchInput').addEventListener('input',ev=>{state.search=ev.target.value;state.page=1;renderTable();});
$('zoneFilter').addEventListener('change',ev=>{state.zone=ev.target.value;state.page=1;renderTable();});
$('statusFilter').addEventListener('change',ev=>{state.status=ev.target.value;state.page=1;renderTable();});
$('pageSize').addEventListener('change',ev=>{state.pageSize=Number(ev.target.value);state.page=1;renderTable();});
$('resetFilters').addEventListener('click',reset);$('emptyReset').addEventListener('click',reset);
const pdfButton=$('exportPdf');if(pdfButton)pdfButton.addEventListener('click',exportPdf);
$('prevPage').addEventListener('click',()=>{state.page--;renderTable();$('catalogTitle').scrollIntoView({block:'start'});});
$('nextPage').addEventListener('click',()=>{state.page++;renderTable();$('catalogTitle').scrollIntoView({block:'start'});});
$('menuButton').addEventListener('click',()=>setMobile(!document.body.classList.contains('nav-open')));$('navShade').addEventListener('click',()=>setMobile(false));
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')setMobile(false);if(ev.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('overviewView').hidden){ev.preventDefault();$('searchInput').focus();}});
window.addEventListener('hashchange',route);metrics();route();
})();
